#!/usr/bin/env bash
# Generates modules/<m>/cinterop@native/opencvkt_<m>.def for every module that has C headers.
#
# Why generated: cinterop resolves relative paths in a .def against its own working directory, so the .def files
# must carry absolute paths to this checkout. They are git-ignored and re-generated by build-native.sh and
# fetch-natives.sh; run this script by hand after cloning if you only compile Kotlin for native targets.
#
# - package     com.jamshedalamqaderi.kmp.opencvkt.<m>.cinterop
# - headers     modules/<m>/include/opencvkt/*.h      (+ -I native/include for the shared opencvkt/prelude.h)
# - modules/core additionally EMBEDS native/prebuilt/<konan_target>/libopencvkt.a for every target that has one,
#   so consumers of any module get OpenCV linked in. A size/mtime stamp of each library is written into the .def,
#   which makes the Kotlin Toolchain re-run cinterop whenever a library is rebuilt.
set -euo pipefail
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
# Paths written into .def files must be native to the OS running cinterop: on Windows (Git Bash / MSYS2),
# convert /c/... into C:/... .
DEF_ROOT="$ROOT"
command -v cygpath >/dev/null 2>&1 && DEF_ROOT="$(cygpath -m "$ROOT")"
PREBUILT="$ROOT/native/prebuilt"
TARGETS=(linux_x64 linux_arm64 mingw_x64 macos_arm64 ios_arm64 ios_simulator_arm64 ios_x64
         android_arm64 android_arm32 android_x64 android_x86)

stamp() { # portable size+mtime
  if stat -c '%s-%Y' "$1" >/dev/null 2>&1; then stat -c '%s-%Y' "$1"; else stat -f '%z-%m' "$1"; fi
}

for dir in "$ROOT"/modules/*/; do
  dir="${dir%/}"
  module="$(basename "$dir")"
  headers_dir="$dir/include/opencvkt"
  compgen -G "$headers_dir/*.h" >/dev/null || continue

  headers="$(cd "$dir/include" && ls opencvkt/*.h | sort | tr '\n' ' ')"
  out_dir="$dir/cinterop@native"
  out="$out_dir/opencvkt_$module.def"
  mkdir -p "$out_dir"
  {
    echo "# GENERATED by scripts/generate-cinterop-defs.sh - do not edit, not committed."
    echo "package = com.jamshedalamqaderi.kmp.opencvkt.$module.cinterop"
    echo "headers = ${headers% }"
    echo "headerFilter = opencvkt/**"
    echo "compilerOpts = -I$DEF_ROOT/modules/$module/include -I$DEF_ROOT/native/include"
    if [[ "$module" == core ]]; then
      missing=()
      for t in "${TARGETS[@]}"; do
        lib="$PREBUILT/$t/libopencvkt.a"
        if [[ -f "$lib" ]]; then
          echo "# $t: libopencvkt.a $(stamp "$lib")"
          echo "staticLibraries.$t = libopencvkt.a"
          echo "libraryPaths.$t = $DEF_ROOT/native/prebuilt/$t"
        else
          missing+=("$t")
        fi
      done
      # System libraries OpenCV needs at final link time (recorded in the klib, applied to every consumer).
      echo "linkerOpts.linux = -ldl -lpthread -lm"
      echo "linkerOpts.mingw = -lole32 -loleaut32 -luuid -lcomdlg32 -lgdi32 -lshlwapi -lstdc++"
      echo "linkerOpts.osx = -framework Foundation -framework CoreFoundation -framework Accelerate -framework AVFoundation -framework CoreMedia -framework CoreVideo -framework CoreGraphics -framework QuartzCore -lc++"
      echo "linkerOpts.ios = -framework Foundation -framework CoreFoundation -framework Accelerate -framework CoreGraphics -framework QuartzCore -framework ImageIO -lc++"
      echo "linkerOpts.android = -lc++_static -lc++abi -llog -landroid -lm -ldl -lz"
      if [[ ${#missing[@]} -gt 0 ]]; then
        echo "note: no libopencvkt.a yet for: ${missing[*]} (their klibs won't embed OpenCV)" >&2
      fi
    fi
  } > "$out"
  echo "generated ${out#"$ROOT/"}"
done
